import {defaults,baseControl,simulate,schemes,ratio} from './physics.mjs';
import {parseData,train,forecast,analogues,mean,keys} from './statistics.mjs';
import {optimise} from './optimise.mjs';
import {fitState,updateParameter,clearEvidence,chatPayload,applyMonitoring,applyGeology} from './state.mjs';
import {catalogue} from './catalog.mjs';
import {esc,num,units,titles,colors,lineChart,panel,table,flow,conclusion,scatter,csv,download} from './charts.mjs';
const nav=[['overview','孪生决策总览','01'],['schemes','措施方案设计','02'],['forecast','生产趋势与概率预测','03'],['optimise','生产参数智能调优','04'],['evaluate','措施效果评价','05'],['models','模型与数据工作台','06'],['report','专家研判与报告','07']];
const S={view:'overview',source:'synthetic',all:[],rows:[],well:'',p:{...defaults},c:{...baseControl},days:60,fit:null,pred:[],model:'ridge',scheme:'fracture',partitions:{},ratios:[70,15,15],opt:null,pick:null,refined:null,algorithm:'NSGA-II',objective:'energy',population:24,iterations:15,monitor:[],geoSource:'默认研究假设，未导入地质解释文件',report:'',service:'',token:'',connected:false,busy:false,error:'',split:'test',target:'oil',log:[]};
const modelName=id=>catalogue.find(x=>x.id===id)?.name??id;
const sourceLabel=()=>S.source==='synthetic'?'合成井组研究场景（非实测）':S.source==='volve'?'Equinor Volve 公开实测抽样':'用户本次上传（来源待用户核实）';
const note=s=>`<p class="audit-note">${s}</p>`;
const btn=(id,label,primary=false)=>`<button class="btn ${primary?'primary':''}" id="${id}" ${S.busy?'disabled':''}>${label}</button>`;
const kpi=(label,value,unit,sub)=>`<div class="kpi"><label>${label}</label><strong>${value}<small>${unit}</small></strong><p>${sub}</p></div>`;
function toast(msg){const x=document.querySelector('#toast');x.textContent=msg;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),3200);}
function log(msg){S.log.unshift(new Date().toLocaleTimeString('zh-CN',{hour12:false})+' '+msg);S.log=S.log.slice(0,20);}
function fail(e){S.error=e.message??String(e);S.busy=false;render();toast(S.error);}
function currentScheme(){return schemes.find(x=>x.id===S.scheme);}
function results(){const start=performance.now(),base=simulate(S.p,S.c,S.days),candidate=simulate(S.p,{...S.c,...currentScheme()},S.days);return {base,candidate,duration:(performance.now()-start)/1000};}
function currentForecast(){if(!S.fit)return [];try{return forecast(S.fit,S.rows,S.days,S.model);}catch{return [];}}
function trainNow(){fitState(S);S.pred=currentForecast();S.report='';log(`实际拟合三类预测器，最佳验证模型：${modelName(S.model)}；测试独立留出`);}
function invalidatePhysics(){clearEvidence(S);}
function invalidateData(){S.fit=null;S.pred=[];S.partitions={};S.report='';S.error='';invalidatePhysics();}
function chooseWell(id){S.well=id;S.rows=S.all.filter(r=>r.well_id===id);invalidateData();try{trainNow();}catch(e){S.error=e.message;}render();}
async function loadSource(value){S.busy=true;S.error='';S.source=value;render();try{const path=value==='volve'?'../agent/data/samples/volve.csv':'../decision/data/production.csv';const r=await fetch(path);if(!r.ok)throw Error(`数据加载失败：${r.status}`);S.all=parseData(await r.text());S.busy=false;chooseWell(S.all[0].well_id);log('已载入：'+sourceLabel());}catch(e){fail(e);}}
function controlField(k,label,unit,group='c',step='any'){const value=group==='p'?S.p[k]:S.c[k];return `<label>${label}<input data-param="${k}" data-group="${group}" type="number" step="${step}" value="${value}" aria-label="${label}"><small>${unit}</small></label>`;}
function shell(body){return `<div class="app" id="shell"><aside class="sidebar"><a class="brand" href="../"><span class="brandmark"><img src="../agent/assets/cnpc-logo.png" alt="中国石油标识"></span><span><strong>ChinaOil Twin</strong><small>RESERVOIR DIGITAL TWIN</small></span></a><div class="space-label">措施设计 · 效果评价</div><nav class="nav">${nav.map(([id,label,no])=>`<button data-nav="${id}" class="${S.view===id?'active':''}" ${S.view===id?'aria-current="page"':''}><span class="nav-icon">${no}</span>${label}</button>`).join('')}</nav><div class="side-foot"><span class="tag red">PPT 48—52 · 工程研究</span><a href="../agent/">↗ 油藏生产态势感知智能体</a><a href="../decision/">↗ 生产动态分析与决策</a><a href="../#simulation">↗ 原平台裂缝与模拟</a><p>统一数据 · 物理约束 · 证据推演</p></div></aside><header class="topbar"><div class="row"><button class="btn phone-menu" id="menu" aria-label="打开导航">☰</button><span class="crumb">智慧油藏 / 孪生措施工作台</span></div><div class="right"><label><span class="muted">数据 </span><select id="source" aria-label="数据来源"><option value="synthetic" ${S.source==='synthetic'?'selected':''}>合成井组研究场景</option><option value="volve" ${S.source==='volve'?'selected':''}>Volve公开实测抽样</option>${S.source==='upload'?'<option value="upload" selected>用户本次上传</option>':''}</select></label><select id="well" aria-label="选择单井">${[...new Set(S.all.map(r=>r.well_id))].map(w=>`<option ${w===S.well?'selected':''}>${esc(w)}</option>`).join('')}</select><span class="service-state badge ${S.connected?'green':''}">${S.connected?'大模型已连接':'本地计算模式'}</span></div></header><main class="main"><div class="head intro"><div><div class="eyebrow">MEASURES DESIGN & PERFORMANCE EVALUATION</div><h1>${nav.find(n=>n[0]===S.view)?.[1]}</h1><p>基于油藏孪生体的油藏开发措施设计与效果评价平台</p></div><div class="row"><span class="tag">当前井 ${esc(S.well||'待载入')}</span>${btn('download-report','导出研究报告')}</div></div><div class="provenance"><span class="badge ${S.source==='volve'?'green':''}">${sourceLabel()}</span><span>${S.rows.length} 条记录 · ${esc(S.rows[0]?.date??'—')} — ${esc(S.rows.at(-1)?.date??'—')}</span><span>预测 ${S.days} 天</span><a href="#models" data-nav="models">查看来源、公式与模型边界</a></div>${S.error?`<div class="error-banner">${esc(S.error)}</div>`:''}${body}<footer><span>ChinaOil Twin · 科研计算工作台 · PPT 48—52</span><div class="footer-links"><span>预测/方案为条件情景，须现场标定与专家复核</span><a href="./README.md">计算方法与数据说明</a><a href="https://github.com/oilreservior123/ChinaOil-platform/tree/main/dist/twin" target="_blank" rel="noopener">GitHub 源码</a></div></footer></main></div>`;}
function twinVisual(){let r;try{r=results().candidate.rows.at(-1);}catch{}return `<div class="twin-visual"><div class="twin-title"><b>油藏—井筒—管网 · 降阶孪生视图</b><span class="badge">示意几何 / 非真实构造</span></div><svg viewBox="0 0 700 290" role="img" aria-label="储层、注水井、生产井与地面管网关系"><defs><linearGradient id="layer" x2="0" y2="1"><stop stop-color="#b98d56" stop-opacity=".75"/><stop offset="1" stop-color="#765336" stop-opacity=".5"/></linearGradient><pattern id="grid" width="35" height="30" patternUnits="userSpaceOnUse"><path d="M35 0H0V30" fill="none" stroke="#b6d5e6" stroke-opacity=".08"/></pattern></defs><rect width="700" height="290" fill="url(#grid)"/><path d="M100 138L390 75L620 140L330 213Z" fill="#8d7758" opacity=".45"/><path d="M100 138L330 213V256L100 183Z" fill="#75553c"/><path d="M330 213L620 140V184L330 256Z" fill="url(#layer)"/><path d="M105 160L330 234L615 162" fill="none" stroke="#bda481" stroke-dasharray="6 5"/><path d="M210 60V175" stroke="#55bbdd" stroke-width="6"/><path d="M480 65V187" stroke="#eaa56b" stroke-width="6"/><path d="M205 59H150V40H480V65" stroke="#cbd7d9" stroke-width="4" fill="none"/><path d="M223 173Q330 129 464 184" fill="none" stroke="#67b7cf" stroke-width="3" stroke-dasharray="8 8"/><circle cx="210" cy="177" r="16" fill="#3f9db3" opacity=".4"/><circle cx="480" cy="189" r="21" fill="#dba463" opacity=".35"/><text x="145" y="25">注水端</text><text x="460" y="25">采出端 / 管网</text><text x="25" y="108">平均地层压力 ${num(r?.pressure??S.p.p)} 兆帕</text><text x="360" y="277">末期含水饱和度 ${num(r?.sw??S.p.sw,4)}</text><text x="255" y="116">PV = φV · 储集系数 C = PVcₜ</text></svg><div class="caption">水相补充 → 压力响应 → 相对渗透率变化 → 油水产量；空间连通仅作示意。</div></div>`;}
function overview(){let a;try{a=results();}catch(e){return `<div class="error-banner">${esc(e.message)}</div>`;}const {base:b,candidate:c}=a;return `<div class="kpis">${kpi('措施情景累计增油',num(c.oil-b.oil,0),'标准立方米',`相对基线，${S.days}日窗口`)}${kpi('综合含水率',num(c.watercut),'%',`基线 ${num(b.watercut)}%，标准体积计算`)}${kpi('单位产油能耗',num(c.specificEnergy),'千瓦时/吨',`假设原油密度0.85吨/标准立方米`)}${kpi('安全约束',c.feasible?'满足':'越界','',c.feasible?'在当前降阶模型与设定边界内':esc(c.violations.join('；')))}</div><div class="hero">${twinVisual()}<div class="hero-right"><button class="action-card" data-nav="schemes"><strong>01　构建与对比措施地质方案</strong><p>等效增导流、控水与配注情景，同一时间窗比较。</p></button><button class="action-card" data-nav="forecast"><strong>02　机理 × 统计 × 案例交叉研判</strong><p>油、水、气、压力、油水比，预测起点与概率包络明确标记。</p></button><button class="action-card" data-nav="optimise"><strong>03　硬约束内寻找可执行方案</strong><p>六项调节变量，三种寻优算法，输出Pareto方案与步长复核。</p></button></div></div><div class="two">${panel('开发动态 · 观测与预测',miniProduction(),'<span class="tag">单井油量</span>')}${panel('PPT 48—52 · 调优闭环',flow(['读取孪生状态','绑定变量与硬约束','模型评估','Pareto迭代','复核','建议与反馈'])+conclusion(`当前采用${esc(currentScheme().name)}，${S.days}日增油情景为${num(c.oil-b.oil)}标准立方米；${c.feasible?'约束可行':'存在安全越界，不应选用'}。这是参数假设下的数值结果，不能作为现场措施成功证据。`)+note('本平台自动化范围为研究计算与建议生成；不向真实设备发送调控指令。'))}</div><div class="warning-legend"><span><i class="severity red"></i><b>红色</b> 硬约束越界，剔除</span><span><i class="severity yellow"></i><b>金色</b> 参数/证据需复核</span><span><i class="severity blue"></i><b>蓝色</b> 统计外推情景</span><span><i class="severity green"></i><b>绿色</b> 仅表示当前计算约束满足</span></div>`;}
function miniProduction(){const h=S.rows.slice(-60),pred=S.pred,labels=h.map(r=>r.date).concat(pred.map(r=>r.date));return lineChart([{name:'观测/输入',values:h.map(r=>r.oil),color:colors.oil},{name:'统计递推',values:h.map(()=>null).concat(pred.map(r=>r.oil.mid)),color:'#3e7a98',dash:true}],{labels,unit:units.oil,split:h.length-1})+conclusion(S.fit?`验证集选出的${esc(modelName(S.model))}给出短期递推情景。独立测试油量RMSE为${num(S.fit.models.find(x=>x.id===S.model).metrics.test.oil.rmse)}标准立方米/日；这是单步误差，不能当作${S.days}日累计预测误差。`:'数据不足以训练；请在模型工作台检查完整字段与时间连续性。');}
function schemeControls(){return `<div class="inline-controls"><label>当前措施<select id="scheme">${schemes.map(s=>`<option value="${s.id}" ${s.id===S.scheme?'selected':''}>${s.name}</option>`).join('')}</select></label><label>预测窗口（天）<input id="days" type="number" min="1" max="180" value="${S.days}"></label>${btn('recompute','重新计算',true)}</div><div class="control-grid gap">${controlField('injection','注水量','标准立方米/日 · 0–900')}${controlField('pwf','井底流压','兆帕 · 8–30')}${controlField('frequency','电潜泵频率','赫兹 · 30–60')}${controlField('network','集输压力','兆帕 · 0.5–4')}${controlField('temperature','加热温度','摄氏度 · 25–65')}${controlField('blend','掺水比例','小数 · 0.05–0.30')}</div>`;}
function schemesView(){const rows=schemes.map(s=>{try{const r=simulate(S.p,{...S.c,...s},S.days);return {id:s.id,方案:s.name,产能倍数:s.gain,水相流度倍数:s.waterFactor,投资:s.cost,累计产油:r.oil,含水率:r.watercut,能耗:r.energy,可行性:r.feasible?'满足':r.violations.join('；')};}catch(e){return {方案:s.name,可行性:e.message};}});const b=simulate(S.p,S.c,S.days),c=simulate(S.p,{...S.c,...currentScheme()},S.days);return `${panel('方案与生产参数',schemeControls(),'<span class="tag">PPT 49 · 可执行变量</span>', '地质属性作为场景条件固定；不将渗透率、孔隙度等不可实时调节的量混入生产参数优化。')}<div class="two gap">${panel('地质与流体输入',`<div class="control-grid">${controlField('p','初始平均地层压力','兆帕 · 用户设定，非Volve井底实测','p')}${controlField('sw','初始含水饱和度','小数0–1','p')}${controlField('J','等效产能指数','地下立方米/(日·兆帕)','p')}${controlField('phi','孔隙度','小数0–1','p')}${controlField('volume','储层总体积','立方米','p')}${controlField('ct','总压缩系数','每兆帕','p')}${controlField('muo','原油黏度','毫帕·秒','p')}${controlField('muw','水黏度','毫帕·秒','p')}${controlField('Bo','原油体积系数','地下体积/标准体积','p')}${controlField('Bw','水体积系数','地下体积/标准体积','p')}${controlField('gor','伴生气油比','标准立方米气/标准立方米油','p')}</div>`)}${panel('硬约束与设备参数',`<div class="control-grid">${controlField('fracture','破裂压力上限','兆帕 · 注水压力不可突破','p')}${controlField('minP','最低地层压力','兆帕','p')}${controlField('maxP','最高地层压力','兆帕','p')}${controlField('maxPower','系统等效功率上限','千瓦 · 水力与显热需求之和','p')}${controlField('depth','泵深','米','p')}${controlField('eta','综合效率','小数0–1','p')}${controlField('injJ','吸水指数','标准立方米/(日·兆帕)','p')}</div>`+conclusion('压裂/酸化用等效产能倍数表征，调剖堵水用水相流度倍数表征；参数由下表给定且可编辑。未求解裂缝扩展或反应运移，方案几何与施工参数仍需专业设计。'))}</div><div class="gap">${panel('方案对比 · 相同地质边界与时间窗',table(rows,[['方案','方案'],['产能倍数','等效产能倍数'],['水相流度倍数','水相流度倍数'],['投资','投资（元）'],['累计产油','累计油（标准立方米）'],['含水率','含水率（%）'],['能耗','能耗（千瓦时）'],['可行性','约束情况']])+`<div class="inline-controls gap"><label>当前措施增导流系数<input id="scheme-gain" type="number" min="0.2" max="3" step=".05" value="${currentScheme().gain}"></label><label>当前措施水相流度倍数<input id="scheme-water" type="number" min=".1" max="2" step=".05" value="${currentScheme().waterFactor}"></label><label>措施投资（元）<input id="scheme-cost" type="number" min="0" value="${currentScheme().cost}"></label>${btn('export-schemes','导出方案表')}</div>`+conclusion(`当前方案末期日产油为${num(c.rows.at(-1).oil)}标准立方米，基线为${num(b.rows.at(-1).oil)}；累计增油${num(c.oil-b.oil)}标准立方米。${c.feasible?'可进入技术经济对比':'存在硬约束越界，不能作为可执行推荐'}。`))}</div>`;}
function forecastView(){const h=S.rows.slice(-60),pred=S.pred,labels=h.map(r=>r.date).concat(pred.map(r=>r.date));let mech;try{mech=results().candidate.rows;}catch{mech=[];}return `${panel('预测配置与证据层次',`<div class="inline-controls"><label>统计预测器<select id="forecast-model">${S.fit?.models.map(m=>`<option value="${m.id}" ${S.model===m.id?'selected':''}>${modelName(m.id)}</option>`).join('')??'<option>尚未训练</option>'}</select></label><label>预测天数<input id="days" type="number" min="1" max="180" value="${S.days}"></label>${btn('predict','运行预测',true)}${btn('export-pred','下载五曲线预测CSV')}</div>`+flow(['石油工程：守恒/分流/产能','统计概率：冻结模型＋验证残差','历史类比：同类地质条件检索'])+note('实线为输入观测，蓝色虚线为统计预测，金色虚线为独立机理情景。预测压力的统计曲线沿用上传测点口径；机理曲线为平均地层压力，二者不作直接精度比较。P10/P90是未校准的残差模拟包络。机理情景以相同相对预测日数展示；若导入了不同时点监测，初值需先人工对齐到生产末日，不能将情景曲线视作同步跟随模拟。'))}<div class="prediction-grid gap">${['oil','water','gas','pressure','owr'].map(k=>{const get=r=>k==='owr'?ratio(r.oil,r.water):r[k],v=h.map(get),future=pred.map(r=>r[k]?.mid??null),last=v.filter(x=>x!==null).at(-1),end=future.at(-1),change=last>0&&end!==null?(end/last-1)*100:null,low=pred.at(-1)?.[k]?.low,high=pred.at(-1)?.[k]?.high;return panel(titles[k]+' · 历史与预测',lineChart([{name:'观测/输入实线',values:v,color:colors[k]},{name:'统计递推虚线',values:v.map(()=>null).concat(future),color:'#3e7a98',dash:true},{name:k==='pressure'?'机理平均地层压力':'机理措施情景',values:v.map(()=>null).concat(mech.map(r=>k==='owr'?r.owr:r[k])),color:'#b68a4c',dash:true}],{labels,unit:units[k],split:h.length-1,band:pred.length?{low:v.map(()=>null).concat(pred.map(r=>r[k]?.low)),high:v.map(()=>null).concat(pred.map(r=>r[k]?.high))}:null})+conclusion(`末期统计中心值为${num(end)} ${units[k]}，相对最新有效观测${change===null?'无法计算变化比例':num(change)+'%'}；模拟包络[${num(low)}, ${num(high)}]。${k==='oil'?'产油趋势需结合递减阶段、注采平衡和措施时点解释；当前统计器不感知未来施工。':k==='water'?'水量变化可能来自液量或分流变化；不能仅凭水量下降确认控水有效。':k==='gas'?'机理气量按固定伴生气油比估算，未求解气相守恒或脱气。':k==='pressure'?'井筒测压与地层平均压力是不同物理量，应按测点和关井条件对齐后再比较。':'油水比定义为油量÷水量；零产水时不可定义，不用0替代。比值升高也可能来自分母下降。'}`),`<span class="unit-pill">${units[k]}</span>`);}).join('')}</div><div class="gap">${caseView()}</div>`;}
function makeCases(){return Array.from({length:12},(_,i)=>({id:'SYN-'+String(i+1).padStart(2,'0'),type:['fracture','acid','water'][i%3],permeability:30+i*17,porosity:.15+i*.007,thickness:8+i*1.3,watercut:25+i*4,uplift:40+Math.sin(i+1)*18+i*3,source:'生成类比样例，非现场历史案例'}));}
let caseRows=makeCases();
function caseView(){const query={permeability:120,porosity:S.p.phi,thickness:18,watercut:results().base.watercut};const same=caseRows.filter(c=>c.type===S.scheme),matches=analogues(same,query);return panel('历史案例视角 · 地质相似度与证据边界',`<div class="data-meta">类比条件：渗透率120毫达西、有效厚度18米（演示查询条件）；孔隙度${num(S.p.phi)}、基线含水率${num(query.watercut)}%。可上传已核实的同类措施案例。</div>`+table(matches,[['id','案例'],['type','措施编码'],['permeability','渗透率（毫达西）'],['porosity','孔隙度'],['thickness','厚度（米）'],['watercut','含水率（%）'],['uplift','窗口累计增油（标准立方米）'],['distance','距离'],['source','来源']])+conclusion(matches.length?`检索到${matches.length}条同类案例，平均窗口增油${num(mean(matches.map(c=>c.uplift)))}标准立方米。${caseRows===null?'':caseRows.some(c=>c.source.includes('生成'))?'默认库为生成样例，仅演示检索，不能作为现场效益或成功率证据。':'上传案例仍需核对施工时间窗、基线与可比性，不能据相似距离认定因果。'}`:'该措施暂无可比案例；不生成无依据的成功率。')+`<div class="uploadbox gap"><label for="case-upload">导入案例JSON（仅本次浏览器内存）</label><input id="case-upload" type="file" accept=".json"><small>数组字段：id,type（fracture/acid/water/injection）,permeability,porosity,thickness,watercut,uplift,source；同一评价时间窗。</small></div>`);}
function optimisationView(){const o=S.opt,a=o?.archive??[],pick=S.pick;return `${panel('智能寻优配置',`<div class="inline-controls"><label>寻优算法<select id="algorithm">${['MOPSO','NSGA-II','GA'].map(x=>`<option ${x===S.algorithm?'selected':''}>${x}</option>`).join('')}</select></label><label>第二目标<select id="objective"><option value="energy" ${S.objective==='energy'?'selected':''}>累计能耗最小</option><option value="water" ${S.objective==='water'?'selected':''}>综合含水率最小</option></select></label><label>种群数<input id="population" type="number" min="8" max="60" value="${S.population}"></label><label>迭代轮数<input id="iterations" type="number" min="2" max="60" value="${S.iterations}"></label><label>窗口（天）<input id="days" type="number" min="1" max="180" value="${S.days}"></label>${btn('run-opt',S.busy?'计算中…':'运行约束寻优',true)}${btn('export-opt','导出Pareto方案')}</div>`+note(`固定地质与措施：${esc(currentScheme().name)}；第一目标始终为累计产油最大。当前直接调用降阶孪生体，未配置代理或全物理仿真。机理硬约束详见措施方案页。`)+table([{变量:'注水量',范围:'100—700',单位:'标准立方米/日',周期:'日—周'},{变量:'井底流压',范围:'12—24',单位:'兆帕',周期:'日—周'},{变量:'泵频',范围:'30—60',单位:'赫兹',周期:'日—周'},{变量:'集输压力',范围:'0.5—3',单位:'兆帕',周期:'小时—日'},{变量:'加热温度',范围:'25—60',单位:'摄氏度',周期:'小时—日'},{变量:'掺水比例',范围:'0.05—0.30',单位:'小数',周期:'小时—日'}],[['变量','变量'],['范围','寻优边界'],['单位','单位'],['周期','调节周期']]))}<div class="two gap">${panel('Pareto前沿 · 可点击选择代表方案',scatter(a,{yKey:S.objective==='water'?'watercut':'energy',yName:S.objective==='water'?'含水率（%）':'能耗（千瓦时）',selectable:true})+conclusion(o?`完成${o.evaluations}次模型求值，用时${num(o.duration,3)}秒，保留${a.length}个非支配可行解。${a.length?'前沿展示增油与'+(S.objective==='water'?'控水':'能耗')+'的取舍，不存在脱离偏好的唯一最优。':'未找到可行方案；需核查约束或工况，系统不推荐越界解。'}`:'运行后展示实际可行解及计算耗时。'),'<span class="tag">非支配解集</span>')}${panel('迭代过程 · 最佳累计产油',lineChart([{name:'档案内最高累计油',values:o?.history.map(h=>h.bestOil)??[],color:colors.oil}],{labels:o?.history.map(h=>h.iteration)??[],unit:'标准立方米',xLabel:'迭代轮数'})+conclusion(o?`首轮最高油量${num(o.history[0].bestOil)}，末轮${num(o.history.at(-1).bestOil)}。前沿档案变化仅反映当前计算搜索过程，不能证明已达到全局最优。`:'待运行寻优。'))}</div><div class="gap">${panel('方案二次选择与数值复核',`<div class="inline-controls">${btn('pick-oil','稳产优先：基线以上低能耗')}${btn('pick-energy','节能优先：基线以下高产油')}${btn('pick-balanced','综合偏好：归一化等权')}${btn('refine','半日步长复核',true)}</div>`+(pick?table([pick.control],[['injection','注水量（标准立方米/日）'],['pwf','井底流压（兆帕）'],['frequency','频率（赫兹）'],['network','集输压力（兆帕）'],['temperature','加热温度（℃）'],['blend','掺水比例']])+conclusion(`所选解累计油${num(pick.oil)}标准立方米、能耗${num(pick.energy)}千瓦时、含水率${num(pick.watercut)}%。${S.refined?`半日步长复核：累计油相对差${num(S.refined.oilError,4)}%，能耗相对差${num(S.refined.energyError,4)}%，约束${S.refined.feasible?'满足':'不满足'}；这只是降阶模型数值收敛检查，不是全仿真复核。`:'尚未进行更小时间步长复核。'}`):'<div class="empty">点击前沿点或按偏好选取方案。</div>')+note('PPT要求的“全仿真复核”需接入已标定油藏—井筒—管网模拟器；此页面不会把步长复核标成已完成全仿真。'))}</div><div class="three gap">${['低风险：微调泵频/间抽，经规则校验后进入执行流程。','中风险：较大注水调整，生成建议并由现场人员确认。','高风险：换泵、调层或措施施工，进入多专业审核。'].map(t=>`<div class="risk-step"><strong>${t.split('：')[0]}</strong><p>${t.split('：')[1]}</p><small>本平台仅输出审核材料，不执行现场下发。</small></div>`).join('')}</div>`;}
function evaluationView(){const {base:b,candidate:c}=results(),labels=c.rows.map(r=>r.day),deltaOil=c.rows.map((r,i)=>r.oil-b.rows[i].oil),cum=[];deltaOil.reduce((s,v,i)=>(cum[i]=s+v),0);const compare=[{项目:'累计产油',基线:b.oil,措施:c.oil,差值:c.oil-b.oil,单位:'标准立方米'},{项目:'累计产水',基线:b.water,措施:c.water,差值:c.water-b.water,单位:'标准立方米'},{项目:'综合含水率',基线:b.watercut,措施:c.watercut,差值:c.watercut-b.watercut,单位:'百分点（差值）'},{项目:'累计能耗',基线:b.energy,措施:c.energy,差值:c.energy-b.energy,单位:'千瓦时'},{项目:'单位产油能耗',基线:b.specificEnergy,措施:c.specificEnergy,差值:c.specificEnergy-b.specificEnergy,单位:'千瓦时/吨'},{项目:'窗口净现值',基线:b.npv,措施:c.npv,差值:c.npv-b.npv,单位:'元'}];return `<div class="kpis">${kpi('累计增油',num(c.oil-b.oil),'标准立方米','同条件反事实基线差分')}${kpi('含水率变化',num(c.watercut-b.watercut),'百分点','负值表示当前情景控水')}${kpi('能耗变化',num((c.energy/b.energy-1)*100),'%','相对维持现状基线')}${kpi('窗口增量净现值',num((c.npv-b.npv)/10000),'万元',`${S.days}天研究假设，不代表全周期收益`)}</div><div class="two">${panel('日产油 · 措施/基线对照',lineChart([{name:'基线',values:b.rows.map(r=>r.oil),color:'#8b929a'},{name:'措施',values:c.rows.map(r=>r.oil),color:colors.oil}],{labels,unit:units.oil,xLabel:'措施后天数'})+conclusion(`措施首日产油${num(c.rows[0].oil)}，末日${num(c.rows.at(-1).oil)}；日增油从${num(deltaOil[0])}变化至${num(deltaOil.at(-1))}标准立方米。压力反馈会使增导流收益随时间改变，不能只用首日产量乘天数估计收益。`))}${panel('累计增油 · 时间演化',lineChart([{name:'累计措施增油',values:cum,color:'#b68a4c'}],{labels,unit:'标准立方米',xLabel:'措施后天数'})+conclusion(`末期累计增油${num(cum.at(-1))}标准立方米；这是同一降阶模型的方案差值，不是观测因果效应。现场评价应另以匹配对照、停产损失与施工时点校正。`))}</div><div class="gap">${panel('技术与经济指标对照',table(compare,[['项目','评价指标'],['基线','基线'],['措施','当前措施'],['差值','措施−基线'],['单位','单位']])+conclusion(`当前措施${c.feasible?'满足设定硬约束':'存在硬约束越界'}；${c.npv-b.npv>0?'在当前窗口与假设成本下增量净现值为正':'当前窗口增量净现值不为正，需复核投资、增油持续时间及全周期现金流'}。经济效益不能覆盖安全约束。`)+`<div class="control-grid gap">${controlField('oilPrice','原油收益假设','元/标准立方米 · 非实时价格','p')}${controlField('waterCost','产水处理成本','元/标准立方米','p')}${controlField('electricity','能源价格假设','元/千瓦时','p')}${controlField('discount','年折现率','小数','p')}</div><div class="row gap">${btn('export-evaluation','导出评价指标CSV')}${btn('export-simulation','导出逐日模拟CSV')}</div>`,'', '净现值未含税费、停产损失、气收益、退役及其他投资；用于研究比选，不是完整项目经济论证。')}</div>`;}
function metricsView(){if(!S.fit)return '<div class="empty">尚未训练；完整同井相邻日样本不足时，系统不生成虚构指标。</div>';const f=S.fit,m=f.models.find(m=>m.id===S.model),r=m.results[S.split],j=keys.indexOf(S.target),data=r.map(x=>({date:x.date,actual:x.actual[j],prediction:x.predicted[j],residual:x.predicted[j]-x.actual[j]})),rows=[];for(const mo of f.models)for(const split of ['train','validation','test'])for(const k of keys){const a=mo.metrics[split][k];rows.push({model:modelName(mo.id),split:{train:'训练',validation:'验证',test:'测试'}[split],target:titles[k],...a,unit:units[k]});}return `<div class="data-meta">原始记录：训练${f.splits.train.length} / 验证${f.splits.validation.length} / 测试${f.splits.test.length}；有效相邻日样本${f.counts.train}/${f.counts.validation}/${f.counts.test}。各分区首日不跨界构造滞后样本。实际记录比例：${[f.splits.train,f.splits.validation,f.splits.test].map(x=>num(x.length/(f.splits.train.length+f.splits.validation.length+f.splits.test.length)*100)).join('/')}%。</div><div class="three gap">${f.models.map(m=>`<div class="data-meta"><strong>${esc(modelName(m.id))}</strong><p>实际拟合/选参耗时：${num(m.duration,4)}秒</p><p>验证归一化RMSE：${num(m.validationScore,4)}</p><p>${f.best===m.id?'✓ 验证集优选模型':'独立候选模型'}</p></div>`).join('')}</div><div class="gap">${table(rows,[['model','模型'],['split','分区'],['target','目标'],['n','样本数'],['mae','MAE'],['rmse','RMSE'],['r2','R²'],['bias','平均偏差'],['unit','误差单位']],36)}</div><div class="inline-controls gap"><label>结果模型<select id="forecast-model">${f.models.map(x=>`<option value="${x.id}" ${S.model===x.id?'selected':''}>${modelName(x.id)}</option>`).join('')}</select></label><label>分区<select id="metric-split">${[['train','训练'],['validation','验证'],['test','测试']].map(([id,n])=>`<option value="${id}" ${S.split===id?'selected':''}>${n}</option>`).join('')}</select></label><label>目标<select id="metric-target">${keys.map(k=>`<option value="${k}" ${S.target===k?'selected':''}>${titles[k]}</option>`).join('')}</select></label>${btn('export-fit','导出全部模型/指标JSON')}</div><div class="two gap">${panel('分区真实值与单步预测',lineChart([{name:'实际输入值',values:data.map(r=>r.actual),color:colors[S.target]},{name:'单步预测',values:data.map(r=>r.prediction),color:'#688c9f',dash:true}],{labels:data.map(r=>r.date),unit:units[S.target]})+conclusion(`当前${{train:'训练',validation:'验证',test:'测试'}[S.split]}集${titles[S.target]}：RMSE ${num(m.metrics[S.split][S.target].rmse)}，R² ${num(m.metrics[S.split][S.target].r2,4)}。${m.metrics[S.split][S.target].r2<0?'R²为负，当前模型弱于该分区均值基线，不宜据此作精确预测。':'误差仅覆盖此井、此时段和单步任务；不能推广为现场通用精度。'}`))}${panel('预测残差 · 偏差检查',lineChart([{name:'预测−实际',values:data.map(r=>r.residual),color:'#b98b46'},{name:'零误差参考',values:data.map(()=>0),color:'#9ea4aa',dash:true}],{labels:data.map(r=>r.date),unit:units[S.target]})+conclusion(`平均偏差为${num(m.metrics[S.split][S.target].bias)} ${units[S.target]}；正值为高估，负值为低估。持续同号或成簇残差提示趋势遗漏或自相关，残差自助包络可能低估长期风险。`))}</div>`;}
function modelCards(){return catalogue.map(m=>`<details class="model-card" ${['tank','ridge'].includes(m.id)?'open':''}><summary>${esc(m.name)}　<span class="badge">${esc(m.kind)}</span></summary><div class="model-content"><div class="two"><div><div class="equation-label">主要数学公式 / 本平台实际实现</div><div class="formula">${esc(m.formula)}</div><p class="audit-note">${esc(m.params)}</p></div><div><div class="architecture">${m.structure.map((x,i)=>`${i?'<div class="arch-arrow">↓</div>':''}<div class="arch-node"><span>${String(i+1).padStart(2,'0')}</span>${esc(x)}</div>`).join('')}</div><div class="data-meta"><b>训练 / 验证 / 测试与耗时</b><p>${esc(m.split)}</p></div></div></div><div class="conclusion"><b>适用条件与边界</b>　${esc(m.limits)}</div></div></details>`).join('');}
function physicalInputs(){return `<div class="gap">${panel('地质与动态监测接入 · 初始化孪生体',`<div class="two"><div class="uploadbox"><label for="geo-upload">地质/流体参数JSON对象</label><input id="geo-upload" type="file" accept=".json"><small>字段：phi,volume,ct,swc,sor,Bo,Bw,muo,muw,J,injJ,gor,depth,eta,fracture；source必填。未提供项保留现值。</small>${btn('geo-template','下载地质参数样例')}</div><div class="uploadbox"><label for="monitor-upload">动态监测JSON数组</label><input id="monitor-upload" type="file" accept=".json"><small>字段：date,reservoir_pressure（平均地层压力，兆帕）,sw（可选）,source；按最新监测初始化储罐压力/饱和度。</small>${btn('monitor-template','下载监测输入样例')}</div></div><div class="data-meta gap">地质来源：${esc(S.geoSource)}；监测：${S.monitor.length?esc(S.monitor.at(-1).date+' / '+S.monitor.at(-1).source):'尚未导入，当前初值为研究假设'}。</div>`+(S.monitor.length?lineChart([{name:'用户提供平均地层压力',values:S.monitor.map(r=>r.reservoir_pressure),color:colors.pressure}],{labels:S.monitor.map(r=>r.date),unit:'兆帕'})+conclusion(`已接入${S.monitor.length}个监测时点，以${esc(S.monitor.at(-1).date)}最新平均地层压力${num(S.p.p)}兆帕初始化孪生体。仅做初值更新，未实现集合卡尔曼滤波或全场历史拟合；井筒测压不能直接替代。`):note('监测样例明确标注生成数据，不伪造实测；不将Volve井筒压力自动当作地层压力。')))}</div>`;}
function modelsView(){return `${physicalInputs()}${panel('统一数据入口 · 单井时间顺序隔离',`<div class="control-grid"><div class="uploadbox"><label for="full-upload">整体生产数据</label><input type="file" id="full-upload" accept=".csv,.json"><small>自动按日期分割；最大5MB、30000行。</small></div>${['train','validation','test'].map((k,i)=>`<div class="uploadbox"><label for="upload-${k}">${['训练集','验证集','测试集'][i]}独立上传</label><input type="file" id="upload-${k}" data-upload="${k}" accept=".csv,.json"><small>${S.partitions[k]?S.partitions[k].length+'行已载入':'未载入'}；三个分区须全部提供、日期严格先后。</small></div>`).join('')}</div><div class="schema">${['well_id（井号）','date（YYYY-MM-DD）','oil（标准立方米/日）','water（标准立方米/日）','gas（标准立方米/日）','pressure（兆帕，测点一致）'].map(k=>`<code>${k}</code>`).join('')}</div><div class="sample">well_id,date,oil,water,gas,pressure\nP-01,2025-01-01,180,100,21600,24\nP-01,2025-01-02,179,101,21480,23.98</div><div class="inline-controls gap">${S.ratios.map((v,i)=>`<label>${['训练','验证','测试'][i]}比例（%）<input data-ratio="${i}" type="number" min="1" max="98" value="${v}"></label>`).join('')}${btn('train','实际拟合三类模型',true)}${btn('clear-partitions','恢复整体数据划分')}${btn('template','下载完整输入样例')}</div>`+note('三类统计预测器均共用以上独立数据入口。按日期而非随机行划分，防止生产时间序列泄漏。上传后仅在内存计算；刷新会清除。机理、优化、案例检索和大模型不伪造监督训练比例。'))}<div class="gap">${panel('训练、验证与测试结果',metricsView())}</div><div class="gap">${modelCards()}</div>${panel('数据来源与专业依据',`<div class="source-list"><p>① 当前${esc(sourceLabel())}；合成井组来自原平台decision/data/production.csv，3口井×180天；Volve来自原agent公开抽样。</p><p>② Volve压力已由bar乘0.1转换为兆帕，来自原生产记录井下测压；不等同实测平均地层压力。油田总注水量不作为单井实测注入。本应用统计训练只取油、水、气、压力与同井日期。</p><p>③ <a href="https://www.equinor.com/energy/volve-data-sharing" target="_blank" rel="noopener">Equinor Volve数据与许可说明</a> · <a href="../agent/data/SOURCES.md">原抽样来源说明</a> · <a href="../decision/data/README.md">合成数据说明</a></p><p>④ <a href="https://opm-project.org/apidoc/latest/opm-autodiff/html/class_opm_1_1_black_oil_model.php" target="_blank" rel="noopener">OPM黑油质量守恒与Darcy多相流文档</a>（理论参照，本页降阶模型不等同OPM求解器）。</p><p>⑤ <a href="https://zenodo.org/records/6487417" target="_blank" rel="noopener">Deb等，NSGA-II原论文</a>；本实现保留非支配排序、拥挤度与精英框架，采用简化算术交叉。</p><p>⑥ 原研究PPT第48—52页只用于需求提炼，不随公开代码上传。</p></div>`)}<div class="historylog gap">${S.log.map(esc).join('<br>')}</div>`;}
function buildReport(){const {base:b,candidate:c,duration}=results(),m=S.fit?.models.find(x=>x.id===S.model);return `基于油藏孪生体的油藏开发措施设计与效果评价报告\n\n一、数据与范围\n地质来源：${S.geoSource}；平均地层监测：${S.monitor.length?S.monitor.at(-1).date+' / '+S.monitor.at(-1).source:'未导入，使用研究假设'}。\n井号：${S.well}；来源：${sourceLabel()}；${S.rows[0]?.date}—${S.rows.at(-1)?.date}，${S.rows.length}条记录；评价窗口${S.days}天。地质与安全参数为用户设定的研究条件。\n\n二、石油与物理依据\n当前措施：${currentScheme().name}。降阶油水储罐＋Corey相渗＋等效井产能；储集系数${num(S.p.phi*S.p.volume*S.p.ct)}地下立方米/兆帕。注入压力≤${S.p.fracture}兆帕，平均压力${S.p.minP}—${S.p.maxP}兆帕，系统功率≤${S.p.maxPower}千瓦。当前${c.feasible?'满足':'不满足'}约束：${c.violations.join('、')||'无越界'}。体积守恒残差${c.balance.toExponential(3)}立方米。本次两方案计算耗时${num(duration,4)}秒。\n\n三、措施效果情景\n基线累计产油${num(b.oil)}，措施${num(c.oil)}，增油${num(c.oil-b.oil)}标准立方米；综合含水率${num(b.watercut)}%→${num(c.watercut)}%；能耗${num(b.energy)}→${num(c.energy)}千瓦时；窗口增量净现值${num(c.npv-b.npv)}元。净现值只基于本窗口和界面成本假设，不构成完整项目评价。\n\n四、统计预测与验证\n${m?`当前预测器：${modelName(m.id)}；训练/验证/测试有效样本${S.fit.counts.train}/${S.fit.counts.validation}/${S.fit.counts.test}。独立测试油量RMSE ${num(m.metrics.test.oil.rmse)}标准立方米/日、R² ${num(m.metrics.test.oil.r2,4)}；实际拟合耗时${num(m.duration,4)}秒。预测P10/P90由验证残差120条递归路径生成，未做覆盖率校准，不等同措施成功概率。`:'完整数据不足，未报告训练或预测精度。'}\n\n五、历史案例证据\n默认案例是明确生成的类比样例，不能证实现场成功率；Volve无确认措施标签，不虚构施工因果。上传案例需复核同类地质、施工条件、时间窗和对照基线。\n\n六、优化与复核\n${S.opt?`${S.opt.algorithm}完成${S.opt.evaluations}次求值，保留${S.opt.archive.length}个可行非支配解，用时${num(S.opt.duration,3)}秒。`:'尚未运行本次优化。'}${S.refined?`所选解半日步长复核：累计油差${num(S.refined.oilError,4)}%，能耗差${num(S.refined.energyError,4)}%。`:'代表解尚无步长复核结果。'}未接入全物理油藏—井筒—管网模拟器，不能宣称已完成全仿真复核。\n\n七、结论与后续建议\n${!c.feasible?'当前措施越界，应先调整参数并重新校验。':c.npv>b.npv?'当前研究窗口内存在正增量效益，可进入现场标定与专家复核。':'当前窗口内尚无正增量经济收益，应复核措施投资、持续效应和全周期现金流。'}压裂/酸化施工和调层等高风险措施应纳入多专业审核；不直接下发真实设备指令。压力统计预测沿用原测点口径，平均地层压力为独立机理变量。\n\n报告模式：${S.connected?'已连接大模型，可另行发起证据研判':'本地计算依据模板，远程大模型未连接'}。`;
}
function reportView(){return `${panel('专家研判 · 计算证据驱动',`<div class="control-grid"><label>大模型网关HTTPS地址<input id="service" type="url" placeholder="https://your-gateway.example" value="${esc(S.service)}"><small>复用decision网关；地址不含/chat。</small></label><label>本次访问令牌<input id="token" type="password" autocomplete="off" value="${esc(S.token)}"><small>只保留在内存，不写入GitHub或浏览器持久存储。</small></label></div><div class="row gap">${btn('connect','检查网关连接')}${btn('llm','发送计算依据并生成研判',true)}${btn('local-report','刷新本地计算报告')}${btn('download-report','下载当前报告')}</div><div class="statusline">${S.connected?'已验证网关配置；模型服务可用':'远程大模型未连接；当前使用本地计算依据模板'}</div>`+note('点击“发送”会把当前井号、来源、指标及模型边界发送至你填写的网关；不发送原始整批生产记录。服务端API密钥与访问控制沿用原decision部署方式。'))}<div class="gap">${panel(S.report?'专家研判输出':'本地计算依据报告',`<div class="report">${esc(S.report||buildReport())}</div>`)}<div class="gap">${panel('执行路径与风险分级',flow(['优化建议','安全规则核验','人工/策略选择','多专业审核','现场执行反馈','孪生同步'])+conclusion('此页面已完成计算与报告链路；云端多人协作、现场执行回写及高保真全仿真需要接入企业服务。按钮不模拟真实审核通过，也不伪造指令下发。'))}</div></div>`;}
function render(){let body='';try{body=S.busy&&S.rows.length===0?'<div class="loading">正在读取数据…</div>':({overview,schemes:schemesView,forecast:forecastView,optimise:optimisationView,evaluate:evaluationView,models:modelsView,report:reportView}[S.view]??overview)();}catch(e){body=`<div class="error-banner">${esc(e.message)}。请在措施方案中修正参数。</div>`;if(S.view==='schemes')body=panel('修正措施输入',schemeControls()+`<div class="control-grid gap">${controlField('p','初始平均地层压力','兆帕','p')}${controlField('sw','初始含水饱和度','小数','p')}${controlField('fracture','破裂压力','兆帕','p')}${controlField('maxPower','功率上限','千瓦','p')}</div>`)+body;}document.querySelector('#app').innerHTML=shell(body);bind();if(S.busy)document.querySelectorAll('main input,main select,.topbar select').forEach(x=>x.disabled=true);}
async function fileRows(file){if(!file||file.size>5*1024*1024)throw Error('请选择不超过5MB的文件');return parseData(await file.text());}
function busyTask(fn){S.busy=true;S.error='';render();setTimeout(()=>{try{fn();S.busy=false;render();}catch(e){fail(e);}},40);}
function pickPreference(mode){if(!S.opt?.archive.length)throw Error('请先运行寻优');const a=S.opt.archive,b=results().base;let candidate;if(mode==='oil')candidate=a.filter(x=>x.oil>=b.oil).toSorted((x,y)=>x.energy-y.energy)[0];else if(mode==='energy')candidate=a.filter(x=>x.energy<=b.energy).toSorted((x,y)=>y.oil-x.oil)[0];else{const oi=a.map(x=>x.oil),en=a.map(x=>S.objective==='water'?x.watercut:x.energy),minO=Math.min(...oi),spanO=Math.max(...oi)-minO||1,minE=Math.min(...en),spanE=Math.max(...en)-minE||1;candidate=a.map((x,i)=>({x,u:(x.oil-minO)/spanO-(en[i]-minE)/spanE})).sort((x,y)=>y.u-x.u)[0].x;}if(!candidate)throw Error('无满足该基线偏好的可行解，请选择其他偏好');S.pick=candidate;S.refined=null;S.report='';render();}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=e=>{e.preventDefault();S.view=b.dataset.nav;location.hash=S.view;render();window.scrollTo(0,0);});document.querySelector('#menu')?.addEventListener('click',()=>document.querySelector('#shell').classList.toggle('menu-open'));
 document.querySelector('#source')?.addEventListener('change',e=>{if(e.target.value!=='upload')loadSource(e.target.value);});document.querySelector('#well')?.addEventListener('change',e=>chooseWell(e.target.value));
 document.querySelectorAll('[data-param]').forEach(x=>x.onchange=()=>{const k=x.dataset.param,v=Number(x.value),group=x.dataset.group;if(!x.value.trim()||!Number.isFinite(v)){toast('请输入有效数值');render();return;}try{updateParameter(S,group,k,v);S.error='';render();}catch(e){fail(e);}});
 document.querySelector('#scheme')?.addEventListener('change',e=>{S.scheme=e.target.value;invalidatePhysics();render();});
 for(const [id,k] of [['scheme-gain','gain'],['scheme-water','waterFactor'],['scheme-cost','cost']])document.getElementById(id)?.addEventListener('change',e=>{const v=Number(e.target.value);if(!Number.isFinite(v)||v<0) return toast('请输入非负数');try{simulate(S.p,{...S.c,...currentScheme(),[k]:v},S.days);currentScheme()[k]=v;invalidatePhysics();S.error='';render();}catch(e){fail(e);}});
 document.querySelector('#days')?.addEventListener('change',e=>{const v=Number(e.target.value);if(!Number.isInteger(v)||v<1||v>180){toast('请输入1—180整数天');render();return;}S.days=v;S.pred=currentForecast();invalidatePhysics();render();});
 document.querySelector('#forecast-model')?.addEventListener('change',e=>{S.model=e.target.value;S.pred=currentForecast();S.report='';render();});
 document.querySelectorAll('[data-ratio]').forEach(x=>x.onchange=()=>{S.ratios[Number(x.dataset.ratio)]=Number(x.value);S.fit=null;S.pred=[];S.report='';render();});
 const on=(id,fn)=>document.querySelectorAll('#'+id).forEach(x=>x.onclick=()=>{try{fn();}catch(e){fail(e);}});
 on('recompute',()=>{results();render();toast('已按当前参数重新计算');});on('predict',()=>{if(!S.fit)throw Error('请先训练模型');S.pred=forecast(S.fit,S.rows,S.days,S.model);S.report='';render();toast('预测完成');});
 on('train',()=>busyTask(()=>{trainNow();toast('实际拟合与独立分区评价已完成');}));on('clear-partitions',()=>{S.partitions={};clearEvidence(S,true);render();toast('已清除独立分区，请重新训练');});
 document.querySelector('#full-upload')?.addEventListener('change',async e=>{try{const a=await fileRows(e.target.files[0]);S.all=a;S.source='upload';chooseWell(a[0].well_id);log('整体上传只保留于内存');}catch(e){fail(e);}});
 document.querySelectorAll('[data-upload]').forEach(x=>x.onchange=async()=>{try{const rows=await fileRows(x.files[0]);if(rows.some(r=>r.well_id!==S.well))throw Error('独立分区只能包含当前选中井：'+S.well);S.partitions[x.dataset.upload]=rows;S.fit=null;S.pred=[];S.report='';S.error='';render();}catch(e){fail(e);}});
 document.querySelector('#metric-split')?.addEventListener('change',e=>{S.split=e.target.value;render();});document.querySelector('#metric-target')?.addEventListener('change',e=>{S.target=e.target.value;render();});
 for(const id of ['algorithm','objective','population','iterations'])document.getElementById(id)?.addEventListener('change',e=>{const v=['population','iterations'].includes(id)?Number(e.target.value):e.target.value;if(typeof v==='number'&&(!Number.isInteger(v)||v<2||v>60)){toast('计算规模需为2—60整数');render();return;}S[id]=v;invalidatePhysics();render();});
 on('run-opt',()=>busyTask(()=>{S.report='';S.opt=optimise(S.p,{algorithm:S.algorithm,objective:S.objective,population:S.population,iterations:S.iterations,days:S.days,scheme:currentScheme()});S.pick=null;S.refined=null;log(`${S.algorithm}：${S.opt.evaluations}次评估，${S.opt.archive.length}个可行前沿方案`);}));
 document.querySelectorAll('[data-pick]').forEach(x=>{const fn=()=>{S.pick=S.opt.archive[Number(x.dataset.pick)];S.refined=null;S.report='';render();};x.onclick=fn;x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn();}};});on('pick-oil',()=>pickPreference('oil'));on('pick-energy',()=>pickPreference('energy'));on('pick-balanced',()=>pickPreference('balanced'));
 on('refine',()=>{if(!S.pick)throw Error('先选择可行方案');const a=simulate(S.p,S.pick.control,S.days,.5);S.refined={oilError:Math.abs(a.oil-S.pick.oil)/a.oil*100,energyError:Math.abs(a.energy-S.pick.energy)/a.energy*100,feasible:a.feasible,balance:a.balance};S.report='';render();});
 for(const [id,handler] of [['geo-upload',applyGeology],['monitor-upload',applyMonitoring]])document.getElementById(id)?.addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f||f.size>2e6)throw Error('JSON文件最大2MB');handler(S,JSON.parse(await f.text()));S.error='';render();toast('已接入孪生体初值与参数');}catch(e){fail(e);}});
 on('geo-template',()=>download('twin-geology-sample.json',JSON.stringify({phi:.22,volume:5e7,ct:.001,swc:.2,sor:.2,Bo:1.15,Bw:1.02,muo:3,muw:.6,J:32,source:'生成研究样例，非实测'},null,2),'application/json'));
 on('monitor-template',()=>download('twin-monitoring-sample.json',JSON.stringify([{date:'2025-07-01',reservoir_pressure:28,sw:.38,source:'生成监测样例，非实测'}],null,2),'application/json'));
 document.querySelector('#case-upload')?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file||file.size>2e6)throw Error('案例文件上限2MB');const a=JSON.parse(await file.text());if(!Array.isArray(a)||!a.length||a.length>1000||a.some(r=>!r.id||!['fracture','acid','water','injection'].includes(r.type)||!r.source||!['permeability','porosity','thickness','watercut','uplift'].every(k=>typeof r[k]==='number'&&Number.isFinite(r[k]))||r.permeability<=0||r.thickness<=0||r.porosity<=0||r.porosity>=1||r.watercut<0||r.watercut>100))throw Error('案例字段、类型或物理范围错误');caseRows=a;S.report='';render();toast('案例已载入，本次刷新后清除');}catch(e){fail(e);}});
 on('template',()=>download('twin-production-sample.csv',csv(S.rows),'text/csv;charset=utf-8'));on('export-fit',()=>{if(!S.fit)throw Error('请先训练');download('twin-model-results.json',JSON.stringify(S.fit,null,2),'application/json');});
 on('export-pred',()=>{if(!S.pred.length)throw Error('暂无预测');download('twin-five-forecasts.csv',csv(S.pred.map(r=>({date:r.date,...Object.fromEntries(['oil','water','gas','pressure','owr'].flatMap(k=>[['P10',r[k].low],['centre',r[k].mid],['P90',r[k].high]].map(([s,v])=>[k+'_'+s,v]))),source:sourceLabel(),model:S.model,interval:'未校准验证残差模拟包络'}))),'text/csv;charset=utf-8');});
 on('export-schemes',()=>download('twin-schemes.csv',csv(schemes.map(s=>{try{const r=simulate(S.p,{...S.c,...s},S.days);return {scheme:s.name,oil:r.oil,watercut:r.watercut,energy:r.energy,npv:r.npv,feasible:r.feasible};}catch(e){return {scheme:s.name,error:e.message};}})),'text/csv;charset=utf-8'));
 on('export-opt',()=>{if(!S.opt?.archive.length)throw Error('没有可行方案');download('twin-pareto.csv',csv(S.opt.archive.map((r,i)=>({id:i+1,...r.control,oil:r.oil,energy:r.energy,watercut:r.watercut,npv:r.npv,feasible:r.feasible,algorithm:S.algorithm,seed:S.opt.seed}))),'text/csv;charset=utf-8');});
 on('export-simulation',()=>download('twin-daily-simulation.csv',csv(results().candidate.rows),'text/csv;charset=utf-8'));on('export-evaluation',()=>{const {base:b,candidate:c}=results();download('twin-evaluation.csv',csv([{scheme:currentScheme().name,days:S.days,deltaOil:c.oil-b.oil,deltaWatercut:c.watercut-b.watercut,deltaEnergy:c.energy-b.energy,deltaNPV:c.npv-b.npv,feasible:c.feasible,source:sourceLabel()}]),'text/csv;charset=utf-8');});
 on('download-report',()=>download('油藏孪生措施设计与效果评价报告.txt',S.report||buildReport()));on('local-report',()=>{S.report='';render();});
 for(const id of ['service','token'])document.getElementById(id)?.addEventListener('input',e=>{S[id]=e.target.value.trim();S.connected=false;S.report='';});
 const endpoint=route=>{const u=new URL(S.service);if(u.protocol!=='https:')throw Error('网关须为HTTPS地址');if(u.username||u.password||u.search||u.hash)throw Error('地址不可包含凭证、查询或锚点');return u.href.replace(/\/$/,'')+route;};
 on('connect',()=>{const url=endpoint('/health');S.busy=true;render();fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+S.token},body:'{}',signal:AbortSignal.timeout(15000)}).then(async r=>{if(!r.ok)throw Error('网关响应'+r.status);const j=await r.json();S.connected=Boolean(j.llm_configured??j.llm?.configured??j.configured);S.busy=false;render();toast(S.connected?'已连接可用大模型服务':'网关可达，但未确认大模型配置，请检查服务');}).catch(fail);});
 on('llm',()=>{if(!S.connected)throw Error('请先检查大模型网关连接');const url=endpoint('/chat'),evidence=buildReport();S.busy=true;render();fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+S.token},body:JSON.stringify(chatPayload('请依据提供的计算结果，从石油、数学与物理角度分析措施方案。不得编造现场成功率、已执行指令或全仿真完成情况。明确约束、不确定性与下一步审核建议。',evidence)),signal:AbortSignal.timeout(90000)}).then(async r=>{if(!r.ok)throw Error('研判服务响应'+r.status);const j=await r.json();if(!j.answer)throw Error('服务未返回answer');S.report=`远程大模型研判（${String(j.model??'模型名未返回')}）\n\n${j.answer}\n\n—— 原始计算证据 ——\n${evidence}`;S.busy=false;render();}).catch(fail);});
}
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(nav.some(n=>n[0]===v)&&S.view!==v){S.view=v;render();}});
